// Churn Summary Tool - n8n Code node (Run Once for All Items)
// Groups all customers by one column and returns churn and revenue metrics,
// plus each group's share of company totals (calculated here, not by the AI model).

const ALLOWED = [
  'none', 'gender', 'SeniorCitizen', 'Partner', 'Dependents', 'tenure_group',
  'PhoneService', 'MultipleLines', 'InternetService', 'OnlineSecurity',
  'OnlineBackup', 'DeviceProtection', 'TechSupport', 'StreamingTV',
  'StreamingMovies', 'Contract', 'PaperlessBilling', 'PaymentMethod'
];

const groupBy = String($('When Executed by Another Workflow').first().json.group_by || 'none').trim();

if (!ALLOWED.includes(groupBy)) {
  return [{ json: { error: `Unsupported group_by "${groupBy}". Use one of: ${ALLOWED.join(', ')}` } }];
}

function tenureGroup(t) {
  if (t <= 12) return '0-12 months';
  if (t <= 24) return '13-24 months';
  if (t <= 48) return '25-48 months';
  return '49-72 months';
}

const round2 = (n) => Math.round(n * 100) / 100;
const groups = {};

for (const item of $input.all()) {
  const c = item.json;
  let key;
  if (groupBy === 'none') key = 'All customers';
  else if (groupBy === 'tenure_group') key = tenureGroup(Number(c.tenure));
  else key = String(c[groupBy]);

  if (!groups[key]) {
    groups[key] = { group: key, customers: 0, churned: 0, monthly_revenue: 0, churned_monthly_revenue: 0, total_charges: 0 };
  }
  const g = groups[key];
  const monthly = Number(c.MonthlyCharges) || 0;
  g.customers += 1;
  g.monthly_revenue += monthly;
  g.total_charges += Number(c.TotalCharges) || 0;
  if (c.Churn === 'Yes') {
    g.churned += 1;
    g.churned_monthly_revenue += monthly;
  }
}

// Company totals, so shares are calculated in code (not by the AI model)
const all = Object.values(groups);
const totalCustomers = all.reduce((s, g) => s + g.customers, 0);
const totalChurned = all.reduce((s, g) => s + g.churned, 0);
const totalMonthly = all.reduce((s, g) => s + g.monthly_revenue, 0);
const totalChurnedMonthly = all.reduce((s, g) => s + g.churned_monthly_revenue, 0);
const pct = (part, whole) => (whole ? round2((part / whole) * 100) : 0);

const rows = all.map((g) => ({
  group: g.group,
  customers: g.customers,
  churned: g.churned,
  churn_rate_pct: round2((g.churned / g.customers) * 100),
  monthly_revenue: round2(g.monthly_revenue),
  churned_monthly_revenue: round2(g.churned_monthly_revenue),
  avg_monthly_charge: round2(g.monthly_revenue / g.customers),
  total_charges: round2(g.total_charges),
  pct_of_customers: pct(g.customers, totalCustomers),
  pct_of_churned_customers: pct(g.churned, totalChurned),
  pct_of_monthly_revenue: pct(g.monthly_revenue, totalMonthly),
  pct_of_churned_revenue: pct(g.churned_monthly_revenue, totalChurnedMonthly),
})).sort((a, b) => b.churn_rate_pct - a.churn_rate_pct);

const totals = {
  customers: totalCustomers,
  churned: totalChurned,
  churn_rate_pct: pct(totalChurned, totalCustomers),
  monthly_revenue: round2(totalMonthly),
  churned_monthly_revenue: round2(totalChurnedMonthly),
  churned_revenue_pct_of_monthly_revenue: pct(totalChurnedMonthly, totalMonthly),
  annualized_churned_revenue: round2(totalChurnedMonthly * 12),
};

return [{ json: { group_by: groupBy, totals, rows } }];
